 const m=structuredClone(r.sourceInputs),s=m.scenarios.find(x=>x.name===(c.sourceScenario||c.sndkScenario)),b=m.capital_bridge,values={...d.bridgeInputs,...overrides};
 if(!s)throw Error('SNDK unknown source scenario.');
