 for(const f of r.bridge.options){const v=values[f.key];if(!finite(v)||(finite(f.min)&&v<f.min)||(finite(f.max)&&v>f.max))throw Error('SNDK funding and claim controls require finite values within their stated bounds.');}
 if(![0,1].includes(values.distributePositiveFcff))throw Error('SNDK distribution policy must be zero or one.');
 const mapping={minimumOperatingCash:'minimum_operating_cash_assumption',securitiesHaircut:'marketable_securities_haircut_assumption',additionalClaimReserve:'additional_claim_reserve_assumption',incrementalUncertainTaxClaim:'incremental_uncertain_tax_claim_assumption',incrementalUnpaidLegal:'incremental_unpaid_legal_assumption'};
 for(const [k,v]of Object.entries(mapping))b[v]=values[k];s.additional_jv_guarantee_call_assumption=values.additionalJvGuaranteeCall;s.terminal_net_physical_jv_funding_floor=values.terminalFundingFloor;s.distribution_policy=values.distributePositiveFcff?'distribute_positive':'retain_all';validateSndkInputs(m,s);
