 if(!d.timing||Object.keys(d.timing).some(k=>!['mode','asOf','stubFCFF','stubDiscountRate','reason'].includes(k))||d.timing.mode!=='origin'||d.discountOrigin!=='2026-07-03'||d.timing.asOf!==d.informationAsOf||d.timing.stubFCFF!==null||!finite(d.timing.stubDiscountRate)||d.timing.stubDiscountRate<=0||d.timing.stubDiscountRate>1)throw Error('SNDK July 3 timing is fixed. A different date requires a newly reviewed capital bridge.');
