 let prior=d.anchor.revenue,cumulative=0,trough=0;
 const rows=o.rows.map((x,i)=>{const a=d.annual[i],growth=x.revenue/prior-1,delta=x.revenue-prior;prior=x.revenue;cumulative+=x.fcff;trough=Math.min(trough,cumulative);return {...a,...x,growth,reinvestment:x.net_reinvestment,requiredInvestment:x.fundingFloor,pv:x.pv_fcff,cumulativeFCFF:cumulative,liquidityAfterReservedClaims:x.funding_cash_pool_before_financing,derivedSalesCapital:x.net_reinvestment?delta/x.net_reinvestment:null};});
